      label('counts',(s.hand_counts || []).map((n,i) => `${playerName(i)} · ${n}`).join('   '),230,690,14);
      if (active && handPage > 0) scene.controls.push({id:'dos_hand_previous',kind:'button',label:text('Previous cards')});
