      const counts = [0,1].map(i => (s.boxes || []).filter(owner => owner === i).length);
      label('scores', `${playerName(0)} · ${counts[0]}    ${playerName(1)} · ${counts[1]}`,
        100, 635, 15);
    } else if (KIND === 'six_mens_morris') {
      const points = [
        [80,70],[310,70],[540,70],[540,300],[540,530],[310,530],[80,530],[80,300],
